contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test function: try calling play with any amount and assert bank is immutable
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // observe bank before
        address bankBefore = c.bank(); if (__ESBMC_reverted()) return;

        bool reverted;
        // call play forwarding `amount` wei
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe bank after
        address bankAfter = c.bank(); if (__ESBMC_reverted()) return;

        // general rule: bank address does not change regardless of inputs or reverts
        assert(bankAfter == bankBefore);
    }

    // allow this test contract to receive Ether to fund calls
    receive() external payable {}
}

